    transform: translateY(-1px);
  }

  .btn:active {
    transform: translateY(0);
  }

  .btn.active {
    background: #3b82f6;
    color: #fff;
    border-color: #60a5fa;
    box-shadow: 0 0 12px rgba(59, 130, 246, 0.4);
  }

  .btn-dot {
    width: 10px;
