    color: #fca5a5;
  }

  .footer-info {
    font-size: 0.75rem;
    color: #64748b;
  }
</style>
</head>
<body>

<div class="container">
  <h1>Sand Simulation</h1>
  <div class="canvas-wrapper">
    <canvas id="sand" width="120" height="120"></canvas>
  </div>
  <div class="controls">
    <button class="btn active" id="mat-sand"><span class="btn-dot"></span>Sand</button>
    <button class="btn" id="mat-water"><span class="btn-dot"></span>Water</button>
    <button class="btn" id="mat-wall"><span class="btn-dot"></span>Wall</button>
    <button class="btn" id="mat-acid"><span class="btn-dot"></span>Acid</button>
    <button class="btn" id="mat-empty"><span class="btn-dot"></span>Eraser</button>
    <button class="btn" id="clear">Clear</button>
  </div>
  <div class="footer-info">Draw: Click & Drag | Acid erodes sand & walls</div>
</div>

<script>
(() => {
  const W = 120;
  const H = 120;
  const canvas = document.getElementById('sand');
  const ctx = canvas.getContext('2d', { willReadFrequently: true });

  const MAT_EMPTY = 0;
  const MAT_SAND = 1;
  const MAT_WATER = 2;
  const MAT_WALL = 3;
  const MAT_ACID = 4;

  const MAT_NAMES = ['empty', 'sand', 'water', 'wall', 'acid'];
  const MAT_MAP = {
    empty: MAT_EMPTY,
    sand: MAT_SAND,
    water: MAT_WATER,
    wall: MAT_WALL,
    acid: MAT_ACID
  };

  const grid = new Uint8Array(W * H);
  const moved = new Uint32Array(W * H);
  let stepCount = 1;

  let currentBrush = 'sand';
  let isPainting = false;

  const imgData = ctx.createImageData(W, H);
  const buf32 = new Uint32Array(imgData.data.buffer);

  // Color lookup (ABGR format for Little Endian)
  const COLORS = new Uint32Array(5);
  COLORS[MAT_EMPTY] = 0xff0b0908; // #08090b
  COLORS[MAT_SAND]  = 0xff28c2f5; // #f5c228 (warm sand)
  COLORS[MAT_WATER] = 0xfff0a020; // #20a0f0 (blue water)
  COLORS[MAT_WALL]  = 0xffa0a094; // #94a0a0 (stone wall)
  COLORS[MAT_ACID]  = 0xff22e645; // #45e622 (bright toxic green)

  function displaceLiquid(fromX, fromY, sandX, sandY, liquidMat) {
    const candidates = [];
    const canLeft = fromX > 0;
    const canRight = fromX < W - 1;

    // Prefer escaping sideways at bottom
    if (canLeft && grid[fromY * W + (fromX - 1)] === MAT_EMPTY) candidates.push([fromX - 1, fromY]);
    if (canRight && grid[fromY * W + (fromX + 1)] === MAT_EMPTY) candidates.push([fromX + 1, fromY]);

    // Or diagonally up-left / up-right
    if (candidates.length === 0) {
      if (canLeft && sandY >= 0 && grid[sandY * W + (fromX - 1)] === MAT_EMPTY) candidates.push([fromX - 1, sandY]);
      if (canRight && sandY >= 0 && grid[sandY * W + (fromX + 1)] === MAT_EMPTY) candidates.push([fromX + 1, sandY]);
    }

    if (candidates.length > 0) {
      const pick = candidates[Math.floor(Math.random() * candidates.length)];
      const pIdx = pick[1] * W + pick[0];
      grid[pIdx] = liquidMat;
      moved[pIdx] = stepCount;
      grid[sandY * W + sandX] = MAT_EMPTY;
    } else {
      // Fallback local swap
      const sIdx = sandY * W + sandX;
      grid[sIdx] = liquidMat;
      moved[sIdx] = stepCount;
    }
  }

  function tickSingle() {
    stepCount++;
    const cur = stepCount;

    // Process bottom-row-up
    for (let y = H - 1; y >= 0; y--) {
      // Alternate horizontal direction to prevent directional drift
      const leftToRight = (y + cur) % 2 === 0;
      const startX = leftToRight ? 0 : W - 1;
      const endX = leftToRight ? W : -1;
      const stepX = leftToRight ? 1 : -1;

      for (let x = startX; x !== endX; x += stepX) {
        const idx = y * W + x;
        const mat = grid[idx];

        if (mat === MAT_EMPTY || mat === MAT_WALL || moved[idx] === cur) {
          continue;
        }

        if (mat === MAT_SAND) {
          if (y + 1 < H) {
            const bIdx = (y + 1) * W + x;
            const bMat = grid[bIdx];

            if (bMat === MAT_EMPTY) {
              grid[bIdx] = MAT_SAND;
              grid[idx] = MAT_EMPTY;
              moved[bIdx] = cur;
              continue;
            } else if (bMat === MAT_WATER || bMat === MAT_ACID) {
              displaceLiquid(x, y + 1, x, y, bMat);
              grid[bIdx] = MAT_SAND;
              moved[bIdx] = cur;
              continue;
            }

            // Blocked straight below; check diagonals
            const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];
            let fell = false;
            for (const dx of dirs) {
              const nx = x + dx;
              if (nx >= 0 && nx < W) {
                const diagIdx = (y + 1) * W + nx;
                const diagMat = grid[diagIdx];
                if (diagMat === MAT_EMPTY) {
                  grid[diagIdx] = MAT_SAND;
                  grid[idx] = MAT_EMPTY;
                  moved[diagIdx] = cur;
                  fell = true;
                  break;
                } else if (diagMat === MAT_WATER || diagMat === MAT_ACID) {
                  displaceLiquid(nx, y + 1, x, y, diagMat);
                  grid[diagIdx] = MAT_SAND;
                  moved[diagIdx] = cur;
                  fell = true;
                  break;
                }
              }
            }
            if (fell) continue;
          }
        } else if (mat === MAT_WATER) {
          if (y + 1 < H) {
            const bIdx = (y + 1) * W + x;
            if (grid[bIdx] === MAT_EMPTY) {
              grid[bIdx] = MAT_WATER;
              grid[idx] = MAT_EMPTY;
              moved[bIdx] = cur;
              continue;
            }

            const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];
            let fell = false;
            for (const dx of dirs) {
              const nx = x + dx;
              if (nx >= 0 && nx < W) {
                const dIdx = (y + 1) * W + nx;
                if (grid[dIdx] === MAT_EMPTY) {
                  grid[dIdx] = MAT_WATER;
                  grid[idx] = MAT_EMPTY;
                  moved[dIdx] = cur;
                  fell = true;
                  break;
                }
              }
            }
            if (fell) continue;
          }

          // Horizontal spread
          const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];
          for (const dx of dirs) {
            const nx = x + dx;
            if (nx >= 0 && nx < W) {
              const sideIdx = y * W + nx;
              if (grid[sideIdx] === MAT_EMPTY) {
                grid[sideIdx] = MAT_WATER;
                grid[idx] = MAT_EMPTY;
                moved[sideIdx] = cur;
                break;
              }
            }
          }
        } else if (mat === MAT_ACID) {
          // Check dissolve reactions with adjacent Sand or Wall
          let dissolved = false;
          // Below
          if (y + 1 < H) {
            const bIdx = (y + 1) * W + x;
            const bMat = grid[bIdx];
            if (bMat === MAT_SAND || bMat === MAT_WALL) {
              grid[bIdx] = MAT_EMPTY;
              grid[idx] = MAT_EMPTY;
              continue;
            }
          }

          // Beside
          const sides = Math.random() < 0.5 ? [-1, 1] : [1, -1];
          for (const dx of sides) {
            const nx = x + dx;
            if (nx >= 0 && nx < W) {
              const sIdx = y * W + nx;
              const sMat = grid[sIdx];
              if (sMat === MAT_SAND || sMat === MAT_WALL) {
                grid[sIdx] = MAT_EMPTY;
                grid[idx] = MAT_EMPTY;
                dissolved = true;
                break;
              }
            }
          }
          if (dissolved) continue;

          // Normal liquid movement if nothing dissolved
          if (y + 1 < H) {
            const bIdx = (y + 1) * W + x;
            if (grid[bIdx] === MAT_EMPTY) {
              grid[bIdx] = MAT_ACID;
              grid[idx] = MAT_EMPTY;
              moved[bIdx] = cur;
              continue;
            }

            const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];
            let fell = false;
            for (const dx of dirs) {
              const nx = x + dx;
              if (nx >= 0 && nx < W) {
                const dIdx = (y + 1) * W + nx;
                if (grid[dIdx] === MAT_EMPTY) {
                  grid[dIdx] = MAT_ACID;
                  grid[idx] = MAT_EMPTY;
                  moved[dIdx] = cur;
                  fell = true;
                  break;
                }
              }
            }
            if (fell) continue;
          }

          // Horizontal spread
          const spreadDirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];
          for (const dx of spreadDirs) {
            const nx = x + dx;
            if (nx >= 0 && nx < W) {
              const sideIdx = y * W + nx;
              if (grid[sideIdx] === MAT_EMPTY) {
                grid[sideIdx] = MAT_ACID;
                grid[idx] = MAT_EMPTY;
                moved[sideIdx] = cur;
                break;
              }
            }
          }
        }
      }
    }
  }

  function render() {
    for (let i = 0; i < W * H; i++) {
      buf32[i] = COLORS[grid[i]];
    }
    ctx.putImageData(imgData, 0, 0);
  }

  // Programmatic API
  window.sim = {
    w: W,
    h: H,
    tick(n = 1) {
      for (let i = 0; i < n; i++) {
        tickSingle();
      }
      render();
    },
    get(x, y) {
      if (x < 0 || x >= W || y < 0 || y >= H) return 'empty';
      return MAT_NAMES[grid[y * W + x]] || 'empty';
    },
    set(x, y, material) {
      if (x >= 0 && x < W && y >= 0 && y < H) {
        grid[y * W + x] = MAT_MAP[material] !== undefined ? MAT_MAP[material] : MAT_EMPTY;
        render();
      }
    },
    clear() {
      grid.fill(MAT_EMPTY);
      render();
    }
  };

  // UI Button Bindings
  const buttons = {
    sand: document.getElementById('mat-sand'),
    water: document.getElementById('mat-water'),
    wall: document.getElementById('mat-wall'),
    acid: document.getElementById('mat-acid'),
    empty: document.getElementById('mat-empty')
  };

  function selectMaterial(mat) {
    currentBrush = mat;
    Object.keys(buttons).forEach(k => {
      if (k === mat) {
        buttons[k].classList.add('active');
      } else {
        buttons[k].classList.remove('active');
      }
    });
  }

  Object.keys(buttons).forEach(mat => {
    buttons[mat].addEventListener('click', () => selectMaterial(mat));
  });

  document.getElementById('clear').addEventListener('click', () => {
    window.sim.clear();
  });

  // Painting interaction
  function paintAtEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const clientX = e.clientX || (e.touches && e.touches[0].clientX);
    const clientY = e.clientY || (e.touches && e.touches[0].clientY);
    if (clientX === undefined || clientY === undefined) return;

    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const cx = Math.floor((clientX - rect.left) * scaleX);
    const cy = Math.floor((clientY - rect.top) * scaleY);

    const radius = (currentBrush === 'wall' || currentBrush === 'empty') ? 2 : 1;
    const matVal = MAT_MAP[currentBrush];

    for (let dy = -radius; dy <= radius; dy++) {
      for (let dx = -radius; dx <= radius; dx++) {
        const px = cx + dx;
        const py = cy + dy;
        if (px >= 0 && px < W && py >= 0 && py < H) {
          if (dx * dx + dy * dy <= radius * radius + 0.5) {
            grid[py * W + px] = matVal;
          }
        }
      }
    }
    render();
  }

  canvas.addEventListener('mousedown', (e) => {
    isPainting = true;
    paintAtEvent(e);
  });

  window.addEventListener('mousemove', (e) => {
    if (isPainting) paintAtEvent(e);
  });

  window.addEventListener('mouseup', () => {
    isPainting = false;
  });

  canvas.addEventListener('touchstart', (e) => {
    isPainting = true;
    paintAtEvent(e);
    e.preventDefault();
  }, { passive: false });

  window.addEventListener('touchmove', (e) => {
    if (isPainting) {
      paintAtEvent(e);
      e.preventDefault();
    }
  }, { passive: false });

  window.addEventListener('touchend', () => {
    isPainting = false;
  });

  // Animation Loop
  function loop() {
    tickSingle();
    render();
    requestAnimationFrame(loop);
  }

  render();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
